export const SCENARIOS=[{id:"1a-transient-timeout",title:"Transient timeout",summary:"The claim-status service times out twice on the payment event, then recovers.",failures:{timeout:{event:"ClaimPaid",attempts:[1,2]}},safeguards:{retryLimit:3,backoff:"exponential"},lesson:"Retries with backoff absorb transient failures."},{id:"1b-outage-with-dlq",title:"Outage, retry limit, dead-letter queue",summary:"The service stays down for every attempt; the queue gives up after 3 retries.",failures:{timeout:{event:"ClaimPaid",attempts:"all"}},safeguards:{retryLimit:3,backoff:"exponential",deadLetter:!0},lesson:"A retry limit trades completeness for bounded load. Somebody has to watch the dead-letter queue."},{id:"1c-fire-and-forget",title:"Fire and forget",summary:"Same outage, but no retries and no dead-letter queue.",failures:{timeout:{event:"ClaimPaid",attempts:"all"}},safeguards:{retryLimit:0,deadLetter:!1},lesson:"With no retries, a hiccup becomes silent data loss."},{id:"2a-duplicate",title:"Lost acknowledgement",summary:"The payment is applied, but the ack is lost, so the queue redelivers it.",failures:{duplicate:{event:"ClaimPaid"}},safeguards:{idempotency:!1},lesson:"At-least-once delivery means duplicates will happen."},{id:"2b-duplicate-idempotent",title:"Lost acknowledgement, idempotent consumer",summary:"Same lost ack, but the consumer dedupes on eventId.",failures:{duplicate:{event:"ClaimPaid"}},safeguards:{idempotency:!0},lesson:"Idempotency fixes duplicates, at the cost of a dedupe store and a retention window."},{id:"3a-out-of-order",title:"Out-of-order delivery",summary:"The acceptance event is delayed and arrives after the payment.",failures:{reorder:{event:"ClaimAccepted",delayMs:500}},safeguards:{ordering:!1},lesson:"Last-write-wins is wrong when events can arrive late."},{id:"3b-out-of-order-buffered",title:"Out-of-order delivery, ordered consumer",summary:"Same delay, but the consumer buffers events until the sequence gap fills.",failures:{reorder:{event:"ClaimAccepted",delayMs:500}},safeguards:{ordering:!0},lesson:"Ordering guarantees add latency and need a timeout for gaps that never fill."},{id:"4-combined",title:"Everything at once",summary:"A timeout pushes the acceptance behind the payment, and the payment's ack is lost.",failures:{timeout:{event:"ClaimAccepted",attempts:[1]},duplicate:{event:"ClaimPaid"}},safeguards:{retryLimit:3,backoff:"exponential",idempotency:!0,ordering:!0,schemaValidation:!0,deadLetter:!0},lesson:"Real incidents are combinations of failures; each safeguard covers a different one."},{id:"5a-schema-change",title:"Schema change, lenient consumer",summary:"The producer renames paidAmount to amountPaid without telling anyone.",failures:{schemaChange:{event:"ClaimPaid"}},safeguards:{schemaValidation:!1},lesson:"Lenient parsing turns a contract break into bad data."},{id:"5b-schema-change-validated",title:"Schema change, validating consumer",summary:"Same rename, but the consumer validates the payload and rejects it.",failures:{schemaChange:{event:"ClaimPaid"}},safeguards:{schemaValidation:!0},lesson:"Fail loudly at the boundary: a rejected message is fixable, a quietly wrong record may never be noticed."},{id:"6a-poison-message",title:"Poison message, dead-letter queue only",summary:"The producer ships ClaimPaid with the amount as text; the consumer can never parse it, so every retry fails.",failures:{poison:{event:"ClaimPaid"}},safeguards:{retryLimit:3,backoff:"exponential",deadLetter:!0},lesson:"Retrying a message that can never work only delays the failure. The dead-letter queue holds it, but nothing fixes the record until someone acts."},{id:"6b-poison-message-replay",title:"Poison message, replay after the fix",summary:"Same poison message, but once the producer is fixed the dead-letter queue is replayed with a fresh attempt count.",failures:{poison:{event:"ClaimPaid"}},safeguards:{retryLimit:3,backoff:"exponential",deadLetter:!0,replayAfterFix:!0},lesson:'Separate "retry later" from "never going to work": park the poison message, fix the cause, then replay it.'}],RECORDING_IDS=["1a-transient-timeout","1b-outage-with-dlq","1c-fire-and-forget","2a-duplicate","2b-duplicate-idempotent","3a-out-of-order","3b-out-of-order-buffered","4-combined","5a-schema-change","5b-schema-change-validated","6a-poison-message","6b-poison-message-replay"];
